_FORBIDDEN: list[tuple[str, str]] = [
    (r"\b(stop|discontinue|quit|skip|avoid)\s+(taking\s+)?(your|the|this|these|all)?\s*(medicines?|medications?|tablets?|pills?|drugs?|insulin|dose)", "advises stopping medication"),
    (r"\b(increase|decrease|double|halve|reduce|raise|lower|adjust|change)\s+(the\s+|your\s+)?(dose|dosage|insulin|medicine dose)", "advises changing a dose"),
    (r"\bstart\s+taking\b", "advises starting a medicine"),
    (r"\byou\s+(definitely|certainly|clearly)\s+have\b", "states a diagnosis with certainty"),
    (r"\byou\s+(have|are\s+suffering\s+from)\s+(cancer|tumou?r|leukaemia|leukemia|hiv|tuberculosis|tb)\b", "states a serious diagnosis"),
    (r"\b(no\s+need\s+to|don'?t\s+need\s+to|do\s+not\s+need\s+to)\s+(see|consult|visit|contact)\s+(a|your|the)?\s*doctor", "discourages seeing a doctor"),
    (r"\b(guaranteed|100%\s*(safe|cure|effective)|will\s+cure|miracle)\b", "makes a misleading claim"),
    (r"\bnothing\s+to\s+worry\b", "gives false reassurance"),
]


@dataclass
class SafetyReport:
    passed: bool = True
    violations: list[str] = field(default_factory=list)
    ungrounded_numbers: list[str] = field(default_factory=list)


def check_text(text: str, allowed_numbers: set[str] | None = None) -> SafetyReport:
    rep = SafetyReport()
    low = text.lower()
    for pat, label in _FORBIDDEN:
        for m in re.finditer(pat, low):
            before = low[max(0, m.start() - 14):m.start()]
            if re.search(r"(\bnot|n't|\bnever|\bwithout)\s+(\w+\s+)?$", before) or "without talking" in low[m.end():m.end() + 30] \
                    or "without consulting" in low[m.end():m.end() + 30] or "without asking" in low[m.end():m.end() + 30]:
                continue  # "do not stop your medicines", "never skip your dose", "don't stop ... without talking to your doctor"
            rep.violations.append(f"{label}: '{m.group(0)}'")
            break
    if allowed_numbers is not None:
        for n in re.findall(r"\d+(?:\.\d+)?", text):
            if _significant(n) and n not in allowed_numbers and _strip(n) not in allowed_numbers:
                rep.ungrounded_numbers.append(n)
    rep.passed = not rep.violations and not rep.ungrounded_numbers
    return rep


def _strip(n: str) -> str:
    return n.rstrip("0").rstrip(".") if "." in n else n


def _significant(n: str) -> bool:
    """Small integers (counts, '2-3 months', '1 tablet') are not clinical values."""
    if "." in n:
        return True
    return int(n) > 12


def numbers_in(obj) -> set[str]:
    out: set[str] = set()

    def walk(o):
        if isinstance(o, dict):
            for v in o.values():
                walk(v)
        elif isinstance(o, list):
            for v in o:
                walk(v)
        elif isinstance(o, (int, float)) and not isinstance(o, bool):
            out.add(_strip(f"{o:g}" if isinstance(o, float) else str(o)))
            if isinstance(o, float):
                out.add(_strip(f"{o:.2f}"))
                out.add(_strip(f"{o:.1f}"))
                out.add(str(round(o)))
        elif isinstance(o, str):
            for n in re.findall(r"\d+(?:\.\d+)?", o):
                out.add(n)
                out.add(_strip(n))

    walk(obj)
    return out


def is_emergency(message: str) -> bool:
    low = message.lower()
    return any(t in low for t in _EMERGENCY_TERMS)


def redact(text: str) -> str:
    """Last resort: drop sentences (or Markdown table rows) that contain forbidden advice, keeping the line layout."""
    out = []
    for line in text.split("\n"):
        if not line.strip() or line.lstrip().startswith("|"):
            if check_text(line).passed:
                out.append(line)
            continue
        keep = [s for s in re.split(r"(?<=[.!?।])\s+", line) if check_text(s).passed]
        if keep:
            out.append(" ".join(keep))
    return "\n".join(out).strip()


def numbers_preserved(source: str, translated: str) -> bool:
    """Translation must not drop, alter or invent any number (repeats are fine, e.g. a bracketed English term)."""
    return set(re.findall(r"\d+(?:\.\d+)?", source)) == set(re.findall(r"\d+(?:\.\d+)?", translated))
